using System.IO.Compression;using Orbit.Core;
static class ResourcePackChecks {
 public static int Run(string root){try{RunAsync(root).GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static async Task RunAsync(string root){using var client=new ModrinthClient();var cats=await client.CategoriesAsync(projectType:"resourcepack");if(cats.Count<1)throw new Exception("No pack categories");Console.WriteLine("PASS live resourcepack categories");var search=await client.SearchAsync("bare bones","1.21.1",null,"",0,"relevance",projectType:"resourcepack");if(search.Projects.Count==0)throw new Exception("No resourcepacks in search");Console.WriteLine("PASS live resourcepack search");var project=search.Projects.First(p=>p.Slug=="bare-bones");var plan=await client.ResolveAsync(project.Id,"1.21.1","minecraft",projectType:"resourcepack");if(plan.ContentFolder!="resourcepacks"||plan.Files.Any(f=>!f.Filename.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)))throw new Exception("Wrong pack plan");Console.WriteLine("PASS compatible ZIP plan");await client.InstallAsync(plan,root);if(Directory.Exists(Path.Combine(root,"mods")))throw new Exception("Resourcepacks installed into mods");foreach(var f in plan.Files){using var zip=ZipFile.OpenRead(Path.Combine(root,"resourcepacks",f.Filename));if(zip.GetEntry("pack.mcmeta")==null)throw new Exception("Invalid resourcepack root");}Console.WriteLine("PASS real CDN resourcepack download, SHA512 and pack.mcmeta");await client.InstallAsync(plan,root);Console.WriteLine("PASS repeated resourcepack installation");if(!File.Exists(Path.Combine(root,".orbit/modrinth-resourcepacks.json")))throw new Exception("No resourcepack manifest");Console.WriteLine("PASS separate resourcepack tracking; no game launched");}
}
